assert len(IDS_B16) == 20 and len(IDS_B17) == 20 and len(IDS_B18) == 20 and len(ALL) == 60

def dump(ids):
    for cid in ids:
        p = f"{P3}/inputs-dev12/{cid}.json"
        with open(p, encoding="utf-8") as f:
            d = json.load(f)
        ctx = d.get("context", {})
        att = ctx.get("attachments", {}) if isinstance(ctx, dict) else {}
        subj = d.get("subject", {})
        print("===", cid, "|trad=", d.get("tradition", "<NONE>"), "|idfield=", d.get("id", d.get("uid", "<none>")))
        print(" subj:", json.dumps(subj, ensure_ascii=False)[:300])
        print(" q:", ctx.get("question"), "| asked:", ctx.get("asked_at"), "| setting:", str(ctx.get("setting"))[:200])
        print(" att:", json.dumps(att, ensure_ascii=False)[:1500])
        print(" ctxfull:", json.dumps(ctx, ensure_ascii=False)[:2000])
        print(" sys/trad:", d.get("system"), "/", d.get("tradition"))
        # any other top-level keys
        extra = {k: v for k, v in d.items() if k not in ("context","subject","tradition","id","uid","provenance","notes")}
        if extra:
            print(" extra:", json.dumps(extra, ensure_ascii=False)[:500])

if __name__ == "__main__":
    import sys
    which = sys.argv[1] if len(sys.argv) > 1 else "b16"
    if which in ("b16", "b17", "b18"):
        dump({"b16": IDS_B16, "b17": IDS_B17, "b18": IDS_B18}[which])

