# ===== writer + per-id verification (no directory listing) =====
def write_all():
    outdir = f"{P3}/runs/round72/predictions"
    tally = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
    written = 0
    for cid in ALL:
        text, basis, conf, trig = PRED[cid]
        rec = {"case_id": cid, "prediction_text": text, "basis": basis, "confidence": conf, "trigger": trig}
        with open(f"{outdir}/{cid}.json", "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
        written += 1
    # verify each file by exact id open
    verified = 0
    for cid in ALL:
        with open(f"{outdir}/{cid}.json", encoding="utf-8") as f:
            rec = json.load(f)
        assert rec["case_id"] == cid and rec["prediction_text"] and rec["basis"] and 0 <= rec["confidence"] <= 1
        assert set(rec["trigger"].keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
        verified += 1
        if cid.startswith("LY-"):
            for k in tally:
                if rec["trigger"][k]:
                    tally[k] += 1
        else:
            assert rec["trigger"] == {"changed_main": False, "reserve_used": False, "disputed": False, "reason": ""}
    print("written", written, "verified", verified, "liuyao_trigger_tally", tally)

if __name__ == "__main__":
    import sys
    if len(sys.argv) > 1 and sys.argv[1] == "write":
        write_all()
    elif len(sys.argv) > 1:
        dump({"b16": IDS_B16, "b17": IDS_B17, "b18": IDS_B18}[sys.argv[1]])
